type Handlers = { [K in Op as K["kind"]]: (op: Extract<Op, { kind: K }>) => Result };

const handlers: Handlers = {
  add: (op) => op.acc + op.value,
  sub: (op) => op.acc - op.value,
};

function dispatch(op: Op): Result {
  return handlers[op.kind](op as never);   // correlation to the narrowed member
}
